// Valida el mensaje, le pone hora de llegada y guarda la última lectura (memoria global)
const p = msg.payload;
if (typeof p !== "object" || p === null || typeof p.nodo !== "number") return null;
p.ts = Date.now();
global.set("ultimo_" + p.nodo, p);
return msg;

// Respaldo completo (formato JSON, una línea por lectura): sirve para n8n / Ollama
const DIR = "C:/agrivoltaico/datos/";
const d = new Date(msg.payload.ts);
const mes = d.getFullYear() + "-" + String(d.getMonth() + 1).padStart(2, "0");
msg.filename = DIR + "telemetria_" + mes + ".jsonl";
msg.payload = JSON.stringify(msg.payload);
return msg;

// CSV para Excel: lecturas crudas, un archivo por nodo y por día
// Si tu Excel abre todo en UNA sola columna o interpreta mal los decimales, cambia estas dos líneas:
const SEP = ";";   // separador de columnas  (";" Excel en español  |  "," Excel en inglés)
const DEC = ",";   // separador decimal      ("," Excel en español  |  "." Excel en inglés)
const DIR = "C:/agrivoltaico/datos/crudo/";

const NOMBRES = { 1: "termico", 2: "radiacion", 3: "cultivo" };
// [clave en el JSON, nombre de la columna, decimales]
const COLUMNAS = {"1": [["pt1", "PT100_1_C", 2], ["pt2", "PT100_2_C", 2], ["pt3", "PT100_3_C", 2], ["temp_amb", "T_ambiente_C", 2], ["hum_amb", "HR_ambiente_pct", 1], ["presion", "Presion_hPa", 1], ["rssi", "RSSI_dBm", 1], ["snr", "SNR_dB", 1]], "2": [["irr", "Irradiancia_Wm2", 0], ["uvi", "UVI", 2], ["v_panel", "V_panel_V", 3], ["i_panel", "I_panel_mA", 1], ["p_panel", "P_panel_mW", 1], ["rssi", "RSSI_dBm", 1], ["snr", "SNR_dB", 1]], "3": [["suelo_temp", "Suelo_T_C", 1], ["suelo_hum", "Suelo_Humedad_pct", 1], ["ec", "EC_uScm", 0], ["sal", "Salinidad", 0], ["nitrogeno", "N_mgkg", 0], ["fosforo", "P_mgkg", 0], ["potasio", "K_mgkg", 0], ["ph", "pH", 1], ["dht_temp", "DHT22_T_C", 1], ["dht_hum", "DHT22_HR_pct", 1], ["caudal", "Caudal_Lmin", 2], ["volumen", "Volumen_L", 3], ["valvula", "Valvula", 0], ["rssi", "RSSI_dBm", 1], ["snr", "SNR_dB", 1]]};

const p = msg.payload;
if (typeof p !== "object" || p === null || !COLUMNAS[p.nodo] || typeof p.ts !== "number") return null;
const cols = COLUMNAS[p.nodo];

const d = new Date(p.ts);
const pad = (n) => String(n).padStart(2, "0");
const dia = d.getFullYear() + "-" + pad(d.getMonth() + 1) + "-" + pad(d.getDate());
const fecha = dia + " " + pad(d.getHours()) + ":" + pad(d.getMinutes()) + ":" + pad(d.getSeconds());
const sufijo = dia;

const fila = [fecha, p.nodo, (typeof p.seq === "number") ? p.seq : ""];
cols.forEach(c => {
    const v = p[c[0]];
    const dec = c[2];
    fila.push(typeof v === "number" ? v.toFixed(dec).replace(".", DEC) : "");
});

const ruta = DIR + "nodo" + p.nodo + "_" + NOMBRES[p.nodo] + "_" + sufijo + ".csv";
let texto = fila.join(SEP);
if (!fs.existsSync(ruta)) {
    // Archivo nuevo: se escribe primero la fila de encabezados
    const cab = ["fecha_hora", "nodo", "seq"].concat(cols.map(c => c[1]));
    texto = cab.join(SEP) + "\n" + texto;
}
msg.filename = ruta;
msg.payload = texto;
return msg;

// Submuestreo: promedio cada 5 min por nodo (promedia TODOS los campos numéricos que lleguen)
const BUCKET_MS = 5 * 60 * 1000;
const MAX_HIST  = 2016;                      // 7 días a 5 min
const EXCLUIR   = ["nodo", "seq", "ts"];

const p = msg.payload;
const n = p.nodo;
const bucket = Math.floor(p.ts / BUCKET_MS);
let acc = flow.get("acc_" + n);
let salida = null;

// Si llegó una lectura de un intervalo nuevo, se cierra el anterior
if (acc && acc.bucket !== bucket) {
    const r = { nodo: n, ts: acc.bucket * BUCKET_MS, muestras: acc.n };
    Object.keys(acc.sum).forEach(k => {
        r[k] = Math.round((acc.sum[k] / acc.cnt[k]) * 100) / 100;
    });

    let h = flow.get("hist_" + n, "file") || [];
    h.push(r);
    if (h.length > MAX_HIST) h = h.slice(-MAX_HIST);
    flow.set("hist_" + n, h, "file");

    salida = { payload: r };
    acc = null;
}

if (!acc) acc = { bucket: bucket, n: 0, sum: {}, cnt: {} };
acc.n++;
Object.keys(p).forEach(k => {
    if (EXCLUIR.includes(k) || typeof p[k] !== "number") return;
    acc.sum[k] = (acc.sum[k] || 0) + p[k];
    acc.cnt[k] = (acc.cnt[k] || 0) + 1;
});
flow.set("acc_" + n, acc);

return salida;

// CSV para Excel: promedios de 5 minutos, un archivo por nodo y por mes
// Si tu Excel abre todo en UNA sola columna o interpreta mal los decimales, cambia estas dos líneas:
const SEP = ";";   // separador de columnas  (";" Excel en español  |  "," Excel en inglés)
const DEC = ",";   // separador decimal      ("," Excel en español  |  "." Excel en inglés)
const DIR = "C:/agrivoltaico/datos/promedios_5min/";

const NOMBRES = { 1: "termico", 2: "radiacion", 3: "cultivo" };
// [clave en el JSON, nombre de la columna, decimales]
const COLUMNAS = {"1": [["pt1", "PT100_1_C", 2], ["pt2", "PT100_2_C", 2], ["pt3", "PT100_3_C", 2], ["temp_amb", "T_ambiente_C", 2], ["hum_amb", "HR_ambiente_pct", 1], ["presion", "Presion_hPa", 1], ["rssi", "RSSI_dBm", 1], ["snr", "SNR_dB", 1]], "2": [["irr", "Irradiancia_Wm2", 0], ["uvi", "UVI", 2], ["v_panel", "V_panel_V", 3], ["i_panel", "I_panel_mA", 1], ["p_panel", "P_panel_mW", 1], ["rssi", "RSSI_dBm", 1], ["snr", "SNR_dB", 1]], "3": [["suelo_temp", "Suelo_T_C", 1], ["suelo_hum", "Suelo_Humedad_pct", 1], ["ec", "EC_uScm", 0], ["sal", "Salinidad", 0], ["nitrogeno", "N_mgkg", 0], ["fosforo", "P_mgkg", 0], ["potasio", "K_mgkg", 0], ["ph", "pH", 1], ["dht_temp", "DHT22_T_C", 1], ["dht_hum", "DHT22_HR_pct", 1], ["caudal", "Caudal_Lmin", 2], ["volumen", "Volumen_L", 3], ["valvula", "Valvula", 0], ["rssi", "RSSI_dBm", 1], ["snr", "SNR_dB", 1]]};

const p = msg.payload;
if (typeof p !== "object" || p === null || !COLUMNAS[p.nodo] || typeof p.ts !== "number") return null;
const cols = COLUMNAS[p.nodo];

const d = new Date(p.ts);
const pad = (n) => String(n).padStart(2, "0");
const dia = d.getFullYear() + "-" + pad(d.getMonth() + 1) + "-" + pad(d.getDate());
const fecha = dia + " " + pad(d.getHours()) + ":" + pad(d.getMinutes()) + ":" + pad(d.getSeconds());
const sufijo = dia.slice(0, 7);

const fila = [fecha, p.nodo, (typeof p.muestras === "number") ? p.muestras : ""];
cols.forEach(c => {
    const v = p[c[0]];
    const dec = (c[2] === 0 ? 1 : c[2]);
    fila.push(typeof v === "number" ? v.toFixed(dec).replace(".", DEC) : "");
});

const ruta = DIR + "nodo" + p.nodo + "_" + NOMBRES[p.nodo] + "_" + sufijo + ".csv";
let texto = fila.join(SEP);
if (!fs.existsSync(ruta)) {
    // Archivo nuevo: se escribe primero la fila de encabezados
    const cab = ["fecha_hora", "nodo", "muestras"].concat(cols.map(c => c[1]));
    texto = cab.join(SEP) + "\n" + texto;
}
msg.filename = ruta;
msg.payload = texto;
return msg;

// ===================== REGLA DE RIEGO (capa determinista) =====================
// Interruptor y deslizadores se manejan desde el dashboard. Si Node-RED se reinicia,
// vuelven a estos valores seguros (automático DESACTIVADO).
const AUTO = global.get("riego_auto") === true;
const UMBRAL_HUM = Number(global.get("riego_umbral") ?? 25);   // % de humedad del suelo
const DUR_RIEGO_S = Number(global.get("riego_dur") ?? 60);     // segundos por riego
// Parámetros fijos (edítalos aquí si hace falta)
const VENTANA = 5;                // lecturas que se promedian (evita reaccionar a un dato suelto)
const MIN_ENTRE_RIEGOS_S = 1800;  // espera mínima entre riegos (para que el agua se infiltre)
const MAX_RIEGOS_DIA = 6;
// Condición de batería: se agregará cuando midamos vbat
// ==============================================================================

const p = msg.payload;
if (typeof p !== "object" || p === null) return null;
const hum = p.suelo_hum;
if (typeof hum !== "number") return null;          // el sensor de suelo no respondió

// Promedio móvil de la humedad
let h = context.get("hist") || [];
h.push(hum);
if (h.length > VENTANA) h = h.slice(-VENTANA);
context.set("hist", h);
const prom = h.reduce((a, b) => a + b, 0) / h.length;

// Contador diario de riegos
const d = new Date();
const hoy = d.getFullYear() + "-" + String(d.getMonth() + 1).padStart(2, "0") + "-" + String(d.getDate()).padStart(2, "0");
if (context.get("dia") !== hoy) { context.set("dia", hoy); context.set("n_dia", 0); }
const nDia = context.get("n_dia") || 0;
const ultimo = context.get("ultimo") || 0;
const ahora = Date.now();

// Decisión: la primera condición que se cumpla impide el riego
let razon = null;
if (!AUTO) razon = "automatico desactivado";
else if (h.length < VENTANA) razon = "reuniendo lecturas";
else if (p.valvula === 1) razon = "ya esta regando";
else if (prom >= UMBRAL_HUM) razon = "humedad suficiente";
else if (ahora - ultimo < MIN_ENTRE_RIEGOS_S * 1000) razon = "esperando entre riegos";
else if (nDia >= MAX_RIEGOS_DIA) razon = "limite diario alcanzado";

const texto = "Regla de riego: " + (razon || "REGANDO") + " | humedad " + prom.toFixed(1) + "% (umbral " + UMBRAL_HUM + "%)";
global.set("riego_estado", texto);
node.status({ fill: razon ? "grey" : "green", shape: "dot", text: texto });

if (razon) {
    // Solo se registra cuando cambia el motivo (evita llenar el registro)
    if (context.get("ultimaRazon") !== razon) {
        context.set("ultimaRazon", razon);
        return [null, { payload: { ts: ahora, evento: "sin_riego", razon: razon, hum_prom: Math.round(prom * 10) / 10 } }];
    }
    return null;
}

context.set("ultimo", ahora);
context.set("n_dia", nDia + 1);
context.set("ultimaRazon", "regando");
return [
    { payload: JSON.stringify({ accion: "abrir", seg: DUR_RIEGO_S }) },
    { payload: { ts: ahora, evento: "riego", seg: DUR_RIEGO_S, hum_prom: Math.round(prom * 10) / 10, umbral: UMBRAL_HUM, riego_n_dia: nDia + 1 } }
];

// Registro de decisiones y eventos de riego: una línea JSON por evento
const DIR = "C:/agrivoltaico/datos/";
const d = new Date();
const mes = d.getFullYear() + "-" + String(d.getMonth() + 1).padStart(2, "0");
msg.filename = DIR + "riego_" + mes + ".jsonl";
const linea = (typeof msg.payload === "object") ? msg.payload : { evento: "mensaje", dato: msg.payload };
if (!linea.ts) linea.ts = Date.now();
msg.payload = JSON.stringify(linea);
return msg;

// Nodo 1 (termico) -> textos y grafica
const p = msg.payload;
const t = (v, dec, u) => (typeof v === "number") ? { payload: v.toFixed(dec) + " " + u } : null;
const s = (nombre, v) => (typeof v === "number") ? { topic: nombre, payload: v } : null;
const graf = [s("PT100 #1", p.pt1), s("PT100 #2", p.pt2), s("PT100 #3", p.pt3), s("Ambiente", p.temp_amb)].filter(x => x);
return [
    t(p.pt1, 2, "°C"), t(p.pt2, 2, "°C"), t(p.pt3, 2, "°C"),
    t(p.temp_amb, 1, "°C"), t(p.hum_amb, 1, "%"), t(p.presion, 1, "hPa"),
    graf.length ? graf : null
];

// Nodo 2 (radiacion y potencia) -> medidores, textos y graficas
const p = msg.payload;
const n = (v) => (typeof v === "number") ? { payload: v } : null;
const t = (v, dec, u) => (typeof v === "number") ? { payload: v.toFixed(dec) + " " + u } : null;
const s = (nombre, v) => (typeof v === "number") ? { topic: nombre, payload: v } : null;
const pW = (typeof p.p_panel === "number") ? p.p_panel / 1000 : undefined;   // mW -> W
return [
    n(p.irr), n(p.uvi),
    t(p.v_panel, 2, "V"), t(p.i_panel, 0, "mA"), t(pW, 2, "W"),
    s("Irradiancia", p.irr), s("Potencia", pW)
];

// Nodo 3 (cultivo) -> medidor, textos y grafica
const p = msg.payload;
const n = (v) => (typeof v === "number") ? { payload: v } : null;
const t = (v, dec, u) => (typeof v === "number") ? { payload: v.toFixed(dec) + (u ? " " + u : "") } : null;
const s = (nombre, v) => (typeof v === "number") ? { topic: nombre, payload: v } : null;
const valv = (typeof p.valvula === "number") ? { payload: p.valvula === 1 ? "ABIERTA" : "CERRADA" } : null;
return [
    n(p.suelo_hum), t(p.suelo_temp, 1, "°C"), t(p.ec, 0, "µS/cm"), t(p.ph, 1, ""),
    t(p.nitrogeno, 0, "mg/kg"), t(p.fosforo, 0, "mg/kg"), t(p.potasio, 0, "mg/kg"),
    t(p.dht_temp, 1, "°C"), t(p.dht_hum, 1, "%"),
    t(p.caudal, 2, "L/min"), t(p.volumen, 3, "L"), valv,
    s("Humedad del suelo", p.suelo_hum)
];

// Promedios de 5 min (llegan del flujo de ingesta) -> graficas de 24 h
const p = msg.payload;
if (!p || typeof p !== "object") return null;
const s = (nombre, v) => (typeof v === "number") ? { topic: nombre, payload: v } : null;
const out = [null, null, null, null];
if (p.nodo === 1) {
    const l = [s("PT100 #1", p.pt1), s("PT100 #2", p.pt2), s("PT100 #3", p.pt3), s("Ambiente", p.temp_amb)].filter(x => x);
    out[0] = l.length ? l : null;
} else if (p.nodo === 2) {
    out[1] = s("Irradiancia", p.irr);
    out[2] = s("Potencia", (typeof p.p_panel === "number") ? p.p_panel / 1000 : undefined);
} else if (p.nodo === 3) {
    out[3] = s("Humedad del suelo", p.suelo_hum);
}
return out;

// Estado del enlace de cada nodo y de la regla de riego (se ejecuta cada 5 s)
const ahora = Date.now();
const salidas = [];
for (const n of [1, 2, 3]) {
    const u = global.get("ultimo_" + n);
    if (!u || !u.ts) { salidas.push({ payload: "Nodo " + n + ": sin datos todavía" }); continue; }
    const seg = Math.round((ahora - u.ts) / 1000);
    const hace = seg < 90 ? seg + " s" : Math.round(seg / 60) + " min";
    if (seg <= 60) salidas.push({ payload: "● Nodo " + n + " en línea · RSSI " + u.rssi + " dBm · SNR " + u.snr + " dB · hace " + hace });
    else salidas.push({ payload: "○ Nodo " + n + " SIN SEÑAL · último dato hace " + hace });
}
salidas.push({ payload: global.get("riego_estado") || "Regla de riego: sin datos todavía" });
return salidas;

// Interruptor y deslizadores del dashboard -> parámetros de la regla de riego
// msg.topic: "auto" | "umbral" | "dur"
const k = "riego_" + msg.topic;
let v = msg.payload;
if (msg.topic === "auto") v = (v === true || v === "true");
else v = Number(v);
global.set(k, v);
node.status({ text: k + " = " + v });
return null;

// Valores seguros al arrancar: automatico apagado
global.set("riego_auto", false);
global.set("riego_umbral", 25);
global.set("riego_dur", 60);
return [{ payload: false }, { payload: 25 }, { payload: 60 }];

// Diagnostico publicado por Node-RED (retenido) -> textos del dashboard
const d = msg.payload;                       // {ts, modelo, duracion_s, valido, diagnostico}
if (!d || !d.diagnostico) return null;
const g = d.diagnostico;
const lista = (a) => (a && a.length) ? a.map(x => "• " + x).join("   ") : "Sin elementos";
const f = new Date(d.ts);
const pad = (n) => String(n).padStart(2, "0");
const fecha = f.getFullYear() + "-" + pad(f.getMonth() + 1) + "-" + pad(f.getDate()) + " " + pad(f.getHours()) + ":" + pad(f.getMinutes());
return [
    { payload: g.resumen || "—" },
    { payload: lista(g.alertas) },
    { payload: lista(g.recomendaciones) },
    { payload: g.prediccion_energia || "—" },
    { payload: "Ultimo diagnostico: " + fecha + " · " + (d.modelo || "") + (d.duracion_s ? " · " + d.duracion_s + " s de calculo" : "") + (d.valido ? "" : " · RESPUESTA NO VALIDA") }
];

// Se ejecuta al pulsar "Abrir" o "Cerrar": avisa en pantalla y vigila que llegue la confirmacion
let a = {};
try { a = JSON.parse(msg.payload); } catch (e) { /* ignorar */ }
const accion = (a.accion === "cerrar") ? "CERRAR" : "ABRIR " + (a.seg || "") + " s";
const t = Date.now();
flow.set("orden_t", t);
const texto = "Orden enviada (" + accion + "). Esperando al gateway...";
setTimeout(() => {
    if (flow.get("orden_t") === t) {
        node.send([{ payload: "Sin confirmacion del nodo 3. Revisa el gateway.", color: "red" },
                   { payload: "SIN CONFIRMACION: la orden (" + accion + ") no fue confirmada" }]);
    }
}, 40000);
return [{ payload: texto, color: "blue" }, { payload: texto }];

// Eventos que publica el gateway sobre la valvula (agri/nodo/3/evento)
const e = msg.payload;
if (!e || typeof e !== "object") return null;
if (e.estado === "recibida") {
    const t = "El gateway recibio la orden #" + e.orden + ". Falta la confirmacion del nodo 3...";
    return [{ payload: t, color: "blue" }, { payload: t }];
}
if (typeof e.valvula === "number") {
    flow.set("orden_t", 0);          // confirmada: se cancela la alarma de falta de confirmacion
    const t = "Nodo 3 confirmo la orden #" + e.orden + ": valvula " + (e.valvula === 1 ? "ABIERTA" : "CERRADA");
    return [{ payload: t, color: "green" }, { payload: t }];
}
return null;

// Resumen de las últimas 24 h para el asesor de IA.
// Lee los CSV de promedios de 5 min (sobreviven a reinicios) y devuelve un JSON compacto.
const SEP = ";";    // deben coincidir con los nodos de CSV del flujo de ingesta
const DEC = ",";
const DIR = "C:/agrivoltaico/datos/";
const HORAS = 24;
const NOMBRES = { 1: "termico", 2: "radiacion", 3: "cultivo" };
const ROL = { 1: "temperaturas (PT100 y aire junto al panel)", 2: "radiacion solar y potencia del panel", 3: "cultivo (suelo, aire y riego)" };
// [columna del CSV, nombre para el modelo, factor]
const VARIABLES = {
    1: [["PT100_1_C", "pt100_1_C"], ["PT100_2_C", "pt100_2_C"], ["PT100_3_C", "pt100_3_C"],
        ["T_ambiente_C", "temp_ambiente_C"], ["HR_ambiente_pct", "humedad_aire_pct"], ["Presion_hPa", "presion_hPa"]],
    2: [["Irradiancia_Wm2", "irradiancia_Wm2"], ["UVI", "indice_uv"], ["V_panel_V", "voltaje_panel_V"],
        ["I_panel_mA", "corriente_panel_mA"], ["P_panel_mW", "potencia_panel_W", 0.001]],
    3: [["Suelo_T_C", "suelo_temp_C"], ["Suelo_Humedad_pct", "suelo_humedad_pct"], ["EC_uScm", "suelo_EC_uScm"],
        ["pH", "suelo_pH"], ["N_mgkg", "N_mgkg"], ["P_mgkg", "P_mgkg"], ["K_mgkg", "K_mgkg"],
        ["DHT22_T_C", "aire_cultivo_temp_C"], ["DHT22_HR_pct", "aire_cultivo_humedad_pct"], ["Caudal_Lmin", "caudal_Lmin"]]
};
// Variables de las que se envía la serie por hora (24 valores)
const SERIES = ["irradiancia_Wm2", "potencia_panel_W", "suelo_humedad_pct", "temp_ambiente_C", "pt100_1_C", "aire_cultivo_humedad_pct"];

const ahora = Date.now();
const desde = ahora - HORAS * 3600e3;
const pad = (n) => String(n).padStart(2, "0");
const mesStr = (d) => d.getFullYear() + "-" + pad(d.getMonth() + 1);
const hoy = new Date(ahora);
const ant = new Date(hoy.getFullYear(), hoy.getMonth() - 1, 1);
const r2 = (v) => (v === null || v === undefined || Number.isNaN(v)) ? null : Math.round(v * 100) / 100;
const media = (x) => x.reduce((a, b) => a + b, 0) / x.length;

function leerCsv(ruta) {
    if (!fs.existsSync(ruta)) return [];
    const lineas = fs.readFileSync(ruta, "utf8").split(/\r?\n/).filter(l => l.length);
    if (lineas.length < 2) return [];
    const cab = lineas[0].split(SEP);
    const filas = [];
    for (let i = 1; i < lineas.length; i++) {
        const c = lineas[i].split(SEP);
        if (c.length !== cab.length) continue;                       // línea dañada
        const m = c[0].match(/^(\d{4})-(\d{2})-(\d{2}) (\d{2}):(\d{2}):(\d{2})$/);
        if (!m) continue;                                            // encabezado repetido u otra basura
        const f = { t: new Date(+m[1], +m[2] - 1, +m[3], +m[4], +m[5], +m[6]).getTime() };
        for (let j = 1; j < cab.length; j++) {
            const v = c[j] === "" ? null : parseFloat(c[j].replace(DEC, "."));
            f[cab[j]] = Number.isNaN(v) ? null : v;
        }
        filas.push(f);
    }
    return filas;
}

// ---- Modo de prueba: /api/resumen24h?demo=1 devuelve datos de EJEMPLO (no son mediciones reales)
const demo = !!(msg.req && msg.req.query && (msg.req.query.demo === "1" || msg.req.query.demo === "true"));
function filasDemo(n) {
    const paso = 5 * 60e3, inicio = Math.floor(ahora / paso) * paso - 287 * paso;
    const filas = [];
    let hum = 34, vol = 0;
    for (let i = 0; i < 288; i++) {
