    return leerCsv(base + mesStr(ant) + ".csv").concat(leerCsv(base + mesStr(hoy) + ".csv"))
        .filter(f => f.t >= desde && f.t <= ahora + 60e3).sort((a, b) => a.t - b.t);
}
function valores(filas, col, factor) {
    return filas.map(f => (typeof f[col] === "number") ? f[col] * (factor || 1) : null);
}
function estadisticas(filas, col, factor) {
    const v = valores(filas, col, factor);
    const val = v.filter(x => x !== null);
    if (!val.length) return null;
    const a = [], b = [];
    filas.forEach((f, i) => {
        if (v[i] === null) return;
        if (f.t >= ahora - 3 * 3600e3) a.push(v[i]);
        else if (f.t >= ahora - 6 * 3600e3) b.push(v[i]);
    });
    return { media: r2(media(val)), min: r2(Math.min(...val)), max: r2(Math.max(...val)), ultimo: r2(val[val.length - 1]),
             cambio_3h: (a.length && b.length) ? r2(media(a) - media(b)) : null };
}
function serieHoraria(filas, col, factor) {
    const out = [];
    for (let h = HORAS; h >= 1; h--) {
        const ini = ahora - h * 3600e3, fin = ahora - (h - 1) * 3600e3;
        const x = filas.filter(f => f.t >= ini && f.t < fin && typeof f[col] === "number").map(f => f[col] * (factor || 1));
        out.push(x.length ? r2(media(x)) : null);
    }
    return out;
}

