    for (const [col, nombre, factor] of VARIABLES[n]) {
        const s = estadisticas(filas, col, factor);
        if (s) o.variables[nombre] = s;
        if (s && SERIES.includes(nombre)) o.serie_horaria[nombre] = serieHoraria(filas, col, factor);
    }
    const paso_h = 5 / 60;   // cada fila es el promedio de 5 min
